import numpy as np

def edge_deployment_pipeline(model, calibration_data, target='mobile'):
    # Prune
    pruned_weights = {}
    for name, w in model.weights.items():
        pruned, mask, sparsity = magnitude_pruning(w, sparsity=0.7)
        pruned_weights[name] = pruned
    # Quantize with calibration
    quantized = int8_quantize(pruned_weights, calibration_data)
    # Export
    if target == 'mobile':
        exported = convert_to_tflite(quantized)
    else:
        exported = convert_to_onnx(quantized)
    # Benchmark
    latency = benchmark(exported, calibration_data)
    size = get_model_size(exported)
    return exported, {'latency_ms': latency, 'size_mb': size}
